 42 | export function isWalkable(x, y, objects = OBJECTS) {
 43 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 44 |   const r = FOUNDER_RADIUS;
 45 |   if (x < r || y < r || x > ROOM.width - r || y > ROOM.depth - r) return false;
 46 |   const pad = 0.05;
 47 |   return !objects.some((o) => x > o.x - pad && x < o.x + o.w + pad && y > o.y - pad && y < o.y + o.d + pad);
 48 | }
