 50 | export function canTravel(from, to, objects = OBJECTS) {
 51 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 52 |   for (let i = 0; i <= steps; i++) {
 53 |     const t = i / steps;
 54 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 55 |   }
 56 |   return true;
 57 | }
