 59 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 60 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 61 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 62 |   // Spiral outward in quarter-tile steps until we find a walkable point
 63 |   const step = 0.25;
 64 |   for (let r = step; r <= 3; r += step) {
 65 |     let best = null, bestDist = Infinity;
 66 |     const n = Math.ceil((r * 2) / step);
 67 |     for (let i = 0; i <= n; i++) {
 68 |       const t = i / n;
 69 |       for (const [cx, cy] of [
 70 |         [tx - r + t * r * 2, ty - r],
 71 |         [tx + r, ty - r + t * r * 2],
 72 |         [tx + r - t * r * 2, ty + r],
 73 |         [tx - r, ty + r - t * r * 2],
 74 |       ]) {
 75 |         const rx = Math.round(cx / step) * step;
 76 |         const ry = Math.round(cy / step) * step;
 77 |         if (!isWalkable(rx, ry, objects)) continue;
 78 |         const d = Math.hypot(rx - tx, ry - ty);
 79 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 80 |       }
 81 |     }
 82 |     if (best) return best;
 83 |   }
 84 |   return null;
 85 | }
