448 | // ── Parkour: blink dash — instant short-range teleport forward ───────────
449 | function tryBlink() {
450 |   if (blinkCooldown > 0) { toast('⚡ Blink recharging…'); return; }
451 |   if (state.energy < 8) { toast('Too drained to blink. Grab a coffee first. ☕'); return; }
452 |   if (paused || dialog.open) return;
453 | 
454 |   // Step forward in direction as far as walkable, up to BLINK_DIST tiles
455 |   const BLINK_DIST = 3.0;
456 |   const STEPS = 24; // resolution of the walk-forward check
457 |   let landX = state.founder.x;
458 |   let landY = state.founder.y;
459 |   for (let i = 1; i <= STEPS; i++) {
460 |     const t = (i / STEPS) * BLINK_DIST;
461 |     const cx = state.founder.x + direction.x * t;
462 |     const cy = state.founder.y + direction.y * t;
463 |     if (!isWalkable(cx, cy)) break;
464 |     landX = cx;
465 |     landY = cy;
466 |   }
467 | 
468 |   const dist = Math.hypot(landX - state.founder.x, landY - state.founder.y);
469 |   if (dist < 0.25) { toast('Nowhere to blink — something is blocking the way.'); return; }
470 | 
471 |   // Stamp a dense burst of ghost positions from current pos to landing pos
472 |   for (let i = 0; i <= 6; i++) {
473 |     const t = i / 6;
474 |     dashTrail.push({
475 |       x: state.founder.x + (landX - state.founder.x) * t,
476 |       y: state.founder.y + (landY - state.founder.y) * t,
477 |       alpha: 0.7 - t * 0.5,
478 |     });
479 |   }
480 |   if (dashTrail.length > 12) dashTrail.splice(0, dashTrail.length - 12);
481 | 
482 |   // Teleport
483 |   state.founder.x = landX;
484 |   state.founder.y = landY;
485 |   changeEnergy(-8);
486 |   blinkCooldown = 1.2;
487 |   complete('parkour');
488 |   updateUI();
489 | }
