403 | function tryVault() {
404 |   if (jumpState || vaultCooldown > 0) return; // already airborne or cooling down
405 |   if (state.energy < 6) { toast('Too drained to jump. Grab a coffee first. ☕'); return; }
406 |   const isSprintJump = (sprinting || dashLocked) && state.energy > 1;
407 |   // Sprint-jump carries further: scale reach and landing distance
408 |   const sprintMult = isSprintJump ? 1.6 : 1.0;
409 |   // Look for a vaultable object in the direction of movement, within reach
410 |   const reach = 2.0 * sprintMult;
411 |   const fx = state.founder.x + direction.x * reach;
412 |   const fy = state.founder.y + direction.y * reach;
413 |   const target = OBJECTS.find(o =>
414 |     VAULTABLE_TYPES.has(o.type) &&
415 |     fx > o.x - 0.4 && fx < o.x + o.w + 0.4 &&
416 |     fy > o.y - 0.4 && fy < o.y + o.d + 0.4
417 |   );
418 |   if (!target) {
419 |     // No object nearby — do a free hop: costs stamina and lands with a stumble
420 |     const hopDist = 1.0 * sprintMult;
421 |     const toX = state.founder.x + direction.x * hopDist;
422 |     const toY = state.founder.y + direction.y * hopDist;
423 |     changeEnergy(-4);
424 |     jumpState = { t: 0, duration: 0.28, fromX: state.founder.x, fromY: state.founder.y, toX, toY, peakHeight: 1.8 + (isSprintJump ? 0.6 : 0), vaultObject: null, freeHop: true, sprintJump: isSprintJump };
425 |     return;
426 |   }
427 |   // Land on the other side: project from object center along movement direction
428 |   const objCx = target.x + target.w / 2;
429 |   const objCy = target.y + target.d / 2;
430 |   const halfExtent = Math.abs(direction.x) > Math.abs(direction.y)
431 |     ? target.w / 2
432 |     : target.d / 2;
433 |   const landDist = (halfExtent + 0.65) * sprintMult;
434 |   const landX = objCx + direction.x * landDist;
435 |   const landY = objCy + direction.y * landDist;
436 |   // Check landing spot is walkable
437 |   if (!isWalkable(landX, landY)) { toast('Nowhere to land! Clear a path first.'); return; }
438 |   // Scale jump height and duration with table span
439 |   const tableSpan = Math.max(target.w, target.d);
440 |   const peakH = (2.5 + tableSpan * 0.5) * (isSprintJump ? 1.25 : 1);
441 |   const dur = (0.30 + tableSpan * 0.06) * (isSprintJump ? 0.8 : 1); // sprint-jump is snappier
442 |   const isShortcutTable = target.type === 'table-vault';
443 |   changeEnergy(isShortcutTable ? -6 : -10);
444 |   jumpState = { t: 0, duration: dur, fromX: state.founder.x, fromY: state.founder.y, toX: landX, toY: landY, peakHeight: peakH, vaultObject: target, sprintJump: isSprintJump };
445 |   playSound('coffee');
