function updateUI() {
  const hour = Math.floor(state.minutes / 60);
  $('#clock').textContent = `${hour % 12 || 12}:${String(Math.floor(state.minutes % 60)).padStart(2, '0')} ${hour >= 12 ? 'PM' : 'AM'}`;
  const energy = Math.round(state.energy);
  $('#energy-value').textContent = String(energy);
  $('#energy-bar').setAttribute('aria-valuenow', String(energy));
  $('#energy-fill').style.width = `${state.energy}%`;
  $('#energy-fill').style.background = '';  // let CSS classes handle colour
  $('#energy-fill').classList.toggle('low', state.energy < 25);
  for (const task of document.querySelectorAll('[data-task]')) {
    const completed = state.completed.includes(task.dataset.task);
    task.classList.toggle('complete', completed);
  }
  $('#founder-hint').style.opacity = state.distance > .2 ? '0' : '1';
  $('#controls-legend').classList.toggle('faded', state.distance > .2 && !paused);
  const soundButton = $('#sound-button');
  soundButton.setAttribute('aria-pressed', String(state.sound));
  soundButton.setAttribute('aria-label', `Turn sound ${state.sound ? 'off' : 'on'}`);
  soundButton.title = `Turn sound ${state.sound ? 'off' : 'on'}`;
  // Day counter in the title
  const dayLabel = state.day < 10 ? `DAY ${state.day} / 10` : `DAY 10 · LAUNCH DAY 🚀`;
  $('#hud-day').textContent = dayLabel;
  // Update work task button label to match current day action
  const workBtn = document.querySelector('[data-task="work"]');
  if (workBtn) {
    const span = workBtn.querySelector('.hud-task-dot');
    workBtn.textContent = '';
    if (span) workBtn.appendChild(span);
    workBtn.append(DAY_PROGRESS[state.day - 1].workAction);
  }
  // Electricity bar
  const elec = Math.round(state.elec);
  $('#elec-value').textContent = String(elec);
  $('#elec-bar').setAttribute('aria-valuenow', String(elec));
  $('#elec-fill').style.width = `${state.elec}%`;
  $('#elec-fill').classList.toggle('low', state.elec < 20);
  // Cycling overlay
  const cyclingOverlay = $('#cycling-overlay');
  if (isCycling) {
    cyclingOverlay.hidden = false;
    cyclingOverlay.classList.toggle('overloaded', bikeBreakdown > 0);
    const pp = pedalPower;
    const pedFill = $('#pedal-fill');
    const chargeLabel = $('#cycling-charge-label');
    const pedalValEl = $('#pedal-val');
    $('#pedal-bar').setAttribute('aria-valuenow', String(Math.round(pp)));
    pedFill.style.width = `${Math.min(pp, 100)}%`;
    pedalValEl.textContent = String(Math.round(Math.min(pp, 100)));
    // Tier classification
    const isBroken   = bikeBreakdown > 0;
    const isTriple   = !isBroken && pp >= 75;
    const isDouble   = !isBroken && pp >= 50 && !isTriple;
    const isNormal   = !isBroken && pp >= 25 && !isTriple && !isDouble;
    pedFill.classList.toggle('broken',  isBroken);
    pedFill.classList.toggle('triple',  isTriple);
    pedFill.classList.toggle('double',  isDouble);
    pedFill.classList.toggle('normal',  isNormal);
    chargeLabel.classList.toggle('broken',  isBroken);
    chargeLabel.classList.toggle('triple',  isTriple);
    chargeLabel.classList.toggle('double',  isDouble);
    chargeLabel.classList.toggle('normal',  isNormal);
    if (isBroken)       chargeLabel.textContent = `💥 OVERLOADED — ${Math.ceil(bikeBreakdown)}s`;
    else if (isTriple)  chargeLabel.textContent = '⚡⚡⚡ TRIPLE CHARGE';
    else if (isDouble)  chargeLabel.textContent = '⚡⚡ DOUBLE CHARGE';
    else if (isNormal)  chargeLabel.textContent = '⚡ CHARGING';
    else                chargeLabel.textContent = 'KEEP PEDALING';
  } else {
    cyclingOverlay.hidden = true;
  }
  // Dash button state
  const dashBtn = $('#dash-button');
  const canBlink = state.energy >= 8 && !paused && blinkCooldown <= 0;
  dashBtn.disabled = !canBlink;
