function advanceDay() {
  if (state.day >= 10) {
    // Win!
    toast('🚀 LAUNCHED! v1.0 is live. You built a startup in ten days. The journey starts now. ✨');
    playSound('complete');
    showDayEnd(true);
    return;
  }
  const completedDay = state.day;
  state.day += 1;
  state.completed = [];
  state.energy = Math.min(100, state.energy + 30); // overnight recovery
  state.minutes = 540; // reset to 9 AM
  state.distance = 0;
  state.founder = { ...START };
  lowEnergyWarned = false;
  energyDrainAccumulator = 0;
  drainInterval = 3;
  speed = 2.65;
  peptideShots = 0;
  sprinting = false; sprintDrainAccumulator = 0; dashTrail = []; dashLocked = false; jumpState = null; vaultCooldown = 0; hopSlowdown = 0; blinkCooldown = 0;
  save();
  updateUI();
  showDayEnd(false, completedDay);
}

function burnOut() {
  paused = true;
  path = [];
  pendingInteraction = null;
  if (dialog.open) dialog.close();
  const completedDay = state.day;
  state.day = Math.min(10, state.day + 1);
  state.completed = [];
  state.energy = 50; // no recovery bonus — penalty for not sleeping
  state.minutes = 540;
  state.distance = 0;
  state.founder = { ...START };
  lowEnergyWarned = false;
  energyDrainAccumulator = 0;
  drainInterval = 3;
  speed = 2.65;
  peptideShots = 0;
  sprinting = false; sprintDrainAccumulator = 0; dashTrail = []; dashLocked = false; jumpState = null; vaultCooldown = 0; hopSlowdown = 0; blinkCooldown = 0;
  save();
  updateUI();
  showDayEnd(false, completedDay, true);
}

function peptideDeath() {
  paused = true;
  path = [];
  pendingInteraction = null;
  if (dialog.open) dialog.close();
  const completedDay = state.day;
  state.day = Math.min(10, state.day + 1);
  state.completed = [];
  state.energy = 30; // harshest penalty — worse than burnout
  state.minutes = 540;
  state.distance = 0;
  state.founder = { ...START };
  lowEnergyWarned = false;
  energyDrainAccumulator = 0;
  drainInterval = 3;
  speed = 2.65;
  peptideShots = 0;
  sprinting = false; sprintDrainAccumulator = 0; dashTrail = []; dashLocked = false; jumpState = null; vaultCooldown = 0; hopSlowdown = 0; blinkCooldown = 0;
  save();
  updateUI();
  showDayEnd(false, completedDay, false, true);
}

function showDayEnd(isWin, completedDay = 0, burnout = false, peptide = false) {
  const overlay = $('#day-end-overlay');
  const title = $('#day-end-title');
  const body = $('#day-end-body');
  const btn = $('#day-end-btn');
  const progress = $('#day-end-progress');

  if (isWin) {
    title.textContent = '🚀 You shipped it.';
    body.textContent = 'Ten days. One product. Countless cups of coffee. v1.0 is live in the world. Whatever comes next, you\'ll figure it out — you always do.';
    btn.textContent = 'Play again';
    progress.textContent = 'LAUNCHED · DAY 10 COMPLETE';
    $('#day-end-bar-fill').style.width = '100%';
  } else if (peptide) {
    const peptideMsgs = [
      'The vial looked so promising. It was not.',
      'Second shot. You knew the odds. You took them anyway.',
      'Three in one day. Nobody does three in one day.',
      'Four shots. You were basically daring it to happen.',
      'You took five peptide shots in one day. There was only one outcome.',
    ];
    title.textContent = '💉 You overdid it.';
    body.textContent = (peptideMsgs[completedDay - 1] || 'The peptide won.') + ' You wake up tomorrow with 30 stamina and a very important lesson learned.';
    btn.textContent = completedDay >= 10 ? 'Try again' : `Crawl into Day ${state.day}`;
    progress.textContent = `DAY ${completedDay} / 10 · PEPTIDE DEATH`;
    $('#day-end-bar-fill').style.width = `${(completedDay / 10) * 100}%`;
  } else if (burnout) {
    const burnoutMsgs = [
      'You hit the wall. It happens. Sleep next time.',
      'Running on fumes only gets you so far.',
      'Even founders need rest. The work will wait.',
      'Crashed before midnight. A lesson in limits.',
      'Burnout is not a badge of honour.',
      'Your body made the call your brain wouldn\'t.',
      'Sometimes the most productive thing is sleep.',
      'Out cold before day\'s end. Rest up.',
      'Almost there — but your stamina gave out first.',
    ];
    title.textContent = '😵 You burned out.';
    body.textContent = (burnoutMsgs[completedDay - 1] || 'You pushed too hard. Sleep next time.') + ' You wake up tomorrow with less stamina than you would have had.';
    btn.textContent = completedDay >= 10 ? 'Try again' : `Crawl into Day ${state.day}`;
    progress.textContent = `DAY ${completedDay} / 10 · BURNED OUT`;
    $('#day-end-bar-fill').style.width = `${(completedDay / 10) * 100}%`;
  } else {
    const msgs = [
      'Prototype logged. Sleep. Try again tomorrow.',
      'Day two in the books. It\'s getting real.',
      'Feedback absorbed. You\'re better for it.',
      'Core flow polished. Four days down.',
      'Halfway to launch. The demo lives.',
      'Paid features built. This is a business.',
      'Rough edges gone. Product shape achieved.',
      'Launch prep done. Two days left.',
      'Final polish shipped. Tomorrow you launch.',
    ];
    title.textContent = `Day ${completedDay} complete.`;
    body.textContent = msgs[completedDay - 1] || 'Another day done. Keep going.';
    btn.textContent = `Start Day ${state.day}`;
    progress.textContent = `DAY ${completedDay} / 10 COMPLETE`;
    $('#day-end-bar-fill').style.width = `${(completedDay / 10) * 100}%`;
  }

  overlay.hidden = false;
  btn.focus();

  btn.onclick = () => {
    overlay.hidden = true;
    if (isWin) {
      // Full reset
      const s = newState(); s.sound = state.sound;
      Object.assign(state, s);
      save(); updateUI();
    }
    paused = false;

