 52 | export function canTravel(from, to, objects = OBJECTS) {
 53 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 54 |   for (let i = 0; i <= steps; i++) {
 55 |     const t = i / steps;
 56 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 57 |   }
 58 |   return true;
 59 | }
