import { OBJECTS, TASKS, SAVE_KEY, START, newState, parseSave, findPath, canTravel, isWalkable, nearestWalkable, DAY_PROGRESS, VAULTABLE_TYPES, getCandidates, WORKER_UPGRADE_COSTS, FOUNDER_UPGRADES } from './world.js';

const $ = (s) => document.querySelector(s);
const canvas = $('#game');
const ctx = canvas.getContext('2d');

// ── Lazy-load renderer ────────────────────────────────────────────────────
let renderer;
async function getRenderer() {
  if (!renderer) {
    const { Renderer } = await import('./renderer.js');
    renderer = new Renderer(canvas, ctx);
  }
  return renderer;
}

// ── State ─────────────────────────────────────────────────────────────────
let state = parseSave(localStorage.getItem(SAVE_KEY));
let path = [];
let pendingInteraction = null;
let clockAccumulator = 0;
let saveAccumulator = 0;
let energyDrainAccumulator = 0;
let electricDrainAccumulator = 0;
let workerEarnAccumulator = 0;
let drainInterval = 3;
let speed = 2.65;
let peptideShots = 0;
let lowEnergyWarned = false;
let lowElecWarned = false;
let direction = { x: 1, y: 0 };
let sprinting = false;
let sprintDrainAccumulator = 0;
let dashTrail = [];
let dashLocked = false;
let jumpState = null;
let vaultCooldown = 0;
let hopSlowdown = 0;
let blinkCooldown = 0;
let sittingOnSofa = false;
let sofaRestAccumulator = 0;
let sofaRecline = 0;
let isCycling = false;
let pedalPower = 0;
let bikeBreakdown = 0;
let audioContext;
let dialogAction = null;
let dialogCancelAction = null;
let dialogKind = null;
const keys = new Set();
const dialog = $('#interaction-dialog');
const hoverLabel = $('#hover-label');
let hovered = null;
let hoverFloor = null;
let storageAvailable = false;
try { localStorage.setItem('_t', '1'); localStorage.removeItem('_t'); storageAvailable = true; } catch {}

// ── Audio ─────────────────────────────────────────────────────────────────
function getAudioContext() {
  if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();
  return audioContext;
}

function playSound(type) {
  if (!state.sound) return;
  try {
    const ac = getAudioContext();
    const o = ac.createOscillator();
    const g = ac.createGain();
    o.connect(g); g.connect(ac.destination);
    const t = ac.currentTime;
    if (type === 'step') {
      o.type = 'triangle'; o.frequency.setValueAtTime(180 + Math.random() * 40, t);
      g.gain.setValueAtTime(0.04, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.08);
      o.start(t); o.stop(t + 0.08);
    } else if (type === 'complete') {
      o.type = 'sine';
      o.frequency.setValueAtTime(520, t); o.frequency.setValueAtTime(780, t + 0.07);
      g.gain.setValueAtTime(0.12, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
      o.start(t); o.stop(t + 0.22);
    } else if (type === 'coffee') {
      o.type = 'sine';
      o.frequency.setValueAtTime(400, t); o.frequency.linearRampToValueAtTime(600, t + 0.15);
      g.gain.setValueAtTime(0.1, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
      o.start(t); o.stop(t + 0.3);
    } else if (type === 'vault') {
      o.type = 'square'; o.frequency.setValueAtTime(320, t); o.frequency.setValueAtTime(640, t + 0.04);
      g.gain.setValueAtTime(0.07, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.18);
      o.start(t); o.stop(t + 0.18);
    } else if (type === 'blink') {
      o.type = 'sawtooth'; o.frequency.setValueAtTime(880, t); o.frequency.exponentialRampToValueAtTime(220, t + 0.12);
      g.gain.setValueAtTime(0.09, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.14);
      o.start(t); o.stop(t + 0.14);
    }
  } catch {}
}

// ── Toast ─────────────────────────────────────────────────────────────────
let toastTimer;
const toastEl = $('#toast');
function toast(msg) {
  toastEl.textContent = msg;
  toastEl.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { toastEl.hidden = true; }, 3200);
}

// ── Save ──────────────────────────────────────────────────────────────────
function save() {
  if (!storageAvailable) return;
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(state)); } catch {}
}

// ── Task completion ───────────────────────────────────────────────────────
function complete(id) {
  if (!state.completed.includes(id)) { state.completed = [...state.completed, id]; }
}

// ── Money & upgrade helpers ───────────────────────────────────────────────
function changeEnergy(amount) { state.energy = Math.max(0, Math.min(100, state.energy + amount)); }
function changeElec(amount)  { state.elec   = Math.max(0, Math.min(100, state.elec   + amount)); }
function changeMoney(amount) { state.money  = Math.max(0, (state.money ?? 0) + amount); }

function hasUpgrade(id) { return (state.founderUpgrades || []).includes(id); }

function workEnergyCost() {
  if (hasUpgrade('deepwork')) return -5;
  if (hasUpgrade('focus'))    return 8;
  return 12;
}

function workMoneyMultiplier() {
  if (hasUpgrade('deepwork'))  return 2.0;
  if (hasUpgrade('speeddesk')) return 1.5;
  return 1.0;
}

function workerEarnings(worker) {
  const level = worker.level || 1;
  return Math.round(worker.earningsPerTick * Math.pow(1.5, level - 1) * 10) / 10;
}

function workerUpgradeCost(worker) {
  const level = worker.level || 1;
  if (level >= 3) return null;
  return WORKER_UPGRADE_COSTS[level];
}

// ── Interactions ──────────────────────────────────────────────────────────
const interactions = {
  plant: {
    icon: 'plant', eyebrow: 'YOUR LEAFY TEAMMATE', title: 'Growth takes time.',
    description: 'No pitch deck. No five-year plan. Just a little sunlight and a little water. Your quietest teammate has the right idea.',
    detail: 'Some days, a green leaf is enough.', action: 'Appreciate the fern',
    perform() { toast('🌿 The fern is doing great. Better than most.'); },
  },
  plan: {
    icon: 'board', eyebrow: 'THE WHITEBOARD',
    get title() { return DAY_PROGRESS[state.day - 1].workTitle; },
    get description() { return DAY_PROGRESS[state.day - 1].workDesc; },
    get detail() { return DAY_PROGRESS[state.day - 1].planDetail; },
    get action() { return state.completed.includes('plan') ? 'Already planned \u2713' : 'Plan the day'; },
    perform() {
      if (state.completed.includes('plan')) { toast('Already planned today. Focus on building.'); return; }
      const d = DAY_PROGRESS[state.day - 1];
      complete('plan'); state.minutes = Math.min(1079, state.minutes + 10);
      toast(d.planToast); playSound('complete');
    },
  },
  work: {
    get icon() { return state.day === 10 ? 'pin' : 'desk'; },
    get eyebrow() { return DAY_PROGRESS[state.day - 1].workEyebrow; },
    get title() { return DAY_PROGRESS[state.day - 1].workTitle; },
    get description() { return DAY_PROGRESS[state.day - 1].workDesc; },
    get detail() {
      const d = DAY_PROGRESS[state.day - 1];
      const mult = workMoneyMultiplier();
      const earned = Math.round(d.workEarnings * mult);
      const energyCost = workEnergyCost();
      const energyStr = energyCost < 0 ? '+' + Math.abs(energyCost) + ' energy' : energyCost + ' energy';
      const multStr = mult > 1 ? ' (' + mult + '\xD7)' : '';
      return d.workDetail + ' \u00B7 +$' + earned.toLocaleString() + multStr + ' \u00B7 ' + energyStr;
    },
    get action() { return DAY_PROGRESS[state.day - 1].workAction; },
    perform() {
      const energyCost = workEnergyCost();
      if (energyCost > 0 && state.energy < energyCost) { toast('Not enough stamina to work. Brew a coffee first.'); return; }
      if (state.elec < 8) { toast('\u26A1 Not enough electricity to run the workstation. Save some power!'); return; }
      const d = DAY_PROGRESS[state.day - 1];
      const mult = workMoneyMultiplier();
      const earned = Math.round(d.workEarnings * mult);
      if (energyCost < 0) { changeEnergy(Math.abs(energyCost)); } else { changeEnergy(-energyCost); }
      changeElec(-8); changeMoney(earned); complete('work'); state.minutes = Math.min(1079, state.minutes + 25);
      const multStr = mult > 1 ? ' (' + mult + '\xD7 boost!)' : '';
      toast(d.workToast.replace('−12 energy', energyCost < 0 ? '+' + Math.abs(energyCost) + ' energy' : energyCost + ' energy') + ' +$' + earned.toLocaleString() + multStr);
      playSound('complete');
    },
  },
  books: {
    icon: 'board',
    get eyebrow() {
      const owned = (state.founderUpgrades || []).length;
      return owned === FOUNDER_UPGRADES.length ? 'FULLY UPGRADED' : 'FOUNDER UPGRADES';
    },
    get title() {
      if ((state.founderUpgrades || []).length === FOUNDER_UPGRADES.length) return 'You\u2019re running at full capacity.';
      const next = FOUNDER_UPGRADES.find(u => !hasUpgrade(u.id));
      return next ? next.name : 'All upgrades purchased.';
    },
    get description() {
      const next = FOUNDER_UPGRADES.find(u => !hasUpgrade(u.id));
      if (!next) return 'Every upgrade is active. Your workspace is optimised, your systems dialled in. Time to scale.';
      return next.description;
    },
    get detail() {
      const owned = (state.founderUpgrades || []).map(id => {
        const u = FOUNDER_UPGRADES.find(u => u.id === id);
        return u ? u.emoji + ' ' + u.name : id;
      });
      const next = FOUNDER_UPGRADES.find(u => !hasUpgrade(u.id));
      const ownedStr = owned.length ? 'Active: ' + owned.join(', ') : 'No upgrades yet';
      if (!next) return ownedStr;
      return ownedStr + ' \u00B7 Next: $' + next.cost.toLocaleString() + ' \u2192 ' + next.effect;
    },
    get action() {
      const next = FOUNDER_UPGRADES.find(u => !hasUpgrade(u.id));
      if (!next) return 'All maxed out \uD83D\uDE80';
      const canAfford = (state.money || 0) >= next.cost;
      return canAfford
        ? 'Buy ' + next.emoji + ' ' + next.name + ' \u2013 $' + next.cost.toLocaleString()
        : 'Need $' + next.cost.toLocaleString() + ' to unlock';
    },
    perform() {
      const next = FOUNDER_UPGRADES.find(u => !hasUpgrade(u.id));
      if (!next) { toast('All founder upgrades are already active. You\u2019re the whole package.'); return; }
      if ((state.money || 0) < next.cost) {
        toast('\uD83D\uDCB0 You need $' + next.cost.toLocaleString() + ' for ' + next.name + '. Keep hustling.'); return;
      }
      changeMoney(-next.cost);
      state.founderUpgrades = [...(state.founderUpgrades || []), next.id];
      toast(next.emoji + ' ' + next.name + ' unlocked! ' + next.effect + '.');
      playSound('complete'); save(); updateUI();
    },
  },
  ideas: {
    icon: 'desk',
    get eyebrow() { return state.workers.some(w => w.deskIndex === 0) ? 'EMPLOYEE DESK' : 'THE OTHER DESK'; },
    get title() {
      const w = state.workers.find(w => w.deskIndex === 0);
      if (w) {
        const level = w.level || 1;
        const cost = workerUpgradeCost(w);
        if (cost === null) return w.name + ' \u00B7 ' + w.emoji + ' ' + w.role + ' \u00B7 MAX LEVEL';
        return w.name + ' \u00B7 ' + w.emoji + ' ' + w.role + ' \u00B7 Level ' + level;
      }
      return 'Room for someone great.';
    },
    get description() {
      const w = state.workers.find(w => w.deskIndex === 0);
      if (w) {
        const eps = workerEarnings(w);
        const cost = workerUpgradeCost(w);
        const levelStr = cost === null ? ' They\u2019re at max level \u2014 a real force multiplier.' : '';
        return w.name + ' is heads-down, earning $' + eps + '/s for the company.' + levelStr;
      }
      return 'For now, it\u2019s a very nice place to spread out your notes. Someday, maybe it\u2019ll be where your first teammate sits. No rush. Good things take a little time.';
    },
    get detail() {
      const w = state.workers.find(w => w.deskIndex === 0);
      if (w) {
        const eps = workerEarnings(w);
        const cost = workerUpgradeCost(w);
        if (cost === null) return 'Earning $' + eps + '/s passively \u00B7 MAX LEVEL';
        const nextEps = Math.round(eps * 1.5 * 10) / 10;
        return 'Earning $' + eps + '/s \u00B7 Upgrade to $' + nextEps + '/s for $' + cost.toLocaleString();
      }
      const candidates = getCandidates(state.day);
      const c = candidates[0];
      return 'Hire ' + c.name + ' (' + c.emoji + ' ' + c.role + ') \u00B7 $' + c.earningsPerTick + '/s';
    },
    get action() {
      const w = state.workers.find(w => w.deskIndex === 0);
      if (!w) return 'Make the offer \uD83E\uDD1D';
      const cost = workerUpgradeCost(w);
      if (cost === null) return 'Max level \u2B50';
      return 'Upgrade ' + w.name + ' \u2013 $' + cost.toLocaleString();
    },
    get cancelLabel() {
      const w = state.workers.find(w => w.deskIndex === 0);
      return w ? 'Let ' + w.name + ' go' : 'Maybe in a minute';
    },
    perform() {
      const w = state.workers.find(w => w.deskIndex === 0);
      if (!w) {
        const c = getCandidates(state.day)[0];
        state.workers = [...state.workers.filter(w => w.deskIndex !== 0), { ...c, deskIndex: 0, level: 1 }];
        toast(c.emoji + ' ' + c.name + ' joined as ' + c.role + '! They\u2019ll earn $' + c.earningsPerTick + '/s passively. \uD83C\uDF89');
        playSound('complete'); save(); updateUI(); return;
      }
      const cost = workerUpgradeCost(w);
      if (cost === null) { toast(w.name + ' is already at max level. You\u2019re running a dream team.'); return; }
      if ((state.money || 0) < cost) { toast('\uD83D\uDCB0 You need $' + cost.toLocaleString() + ' to upgrade ' + w.name + '.'); return; }
      changeMoney(-cost);
      const newLevel = (w.level || 1) + 1;
      state.workers = state.workers.map(wk => wk.deskIndex === 0 ? { ...wk, level: newLevel } : wk);
      const newEps = workerEarnings({ ...w, level: newLevel });
      toast(w.emoji + ' ' + w.name + ' upgraded to Level ' + newLevel + '! Now earning $' + newEps + '/s. \uD83D\uDE80');
      playSound('complete'); save(); updateUI();
    },
    performCancel() {
      const w = state.workers.find(w => w.deskIndex === 0);
      if (w) {
        state.workers = state.workers.filter(wk => wk.deskIndex !== 0);
        toast(w.name + ' has left the building. Good luck out there.');
        save(); updateUI();
      }
    },
  },
  ideas2: {
    icon: 'desk',
    get eyebrow() { return state.workers.some(w => w.deskIndex === 1) ? 'EMPLOYEE DESK' : 'EMPTY DESK'; },
    get title() {
      const w = state.workers.find(w => w.deskIndex === 1);
      if (w) {
        const level = w.level || 1;
        const cost = workerUpgradeCost(w);
        if (cost === null) return w.name + ' \u00B7 ' + w.emoji + ' ' + w.role + ' \u00B7 MAX LEVEL';
        return w.name + ' \u00B7 ' + w.emoji + ' ' + w.role + ' \u00B7 Level ' + level;
      }
      return 'Space for one more.';
    },
    get description() {
      const w = state.workers.find(w => w.deskIndex === 1);
      if (w) {
        const eps = workerEarnings(w);
        const cost = workerUpgradeCost(w);
        const levelStr = cost === null ? ' They\u2019re at max level \u2014 a real force multiplier.' : '';
        return w.name + ' is grinding away, adding $' + eps + '/s to the bottom line.' + levelStr;
      }
      return 'A second desk. Every great company started with two people. Maybe this is where yours does too.';
    },
    get detail() {
      const w = state.workers.find(w => w.deskIndex === 1);
      if (w) {
        const eps = workerEarnings(w);
        const cost = workerUpgradeCost(w);
        if (cost === null) return 'Earning $' + eps + '/s passively \u00B7 MAX LEVEL';
        const nextEps = Math.round(eps * 1.5 * 10) / 10;
        return 'Earning $' + eps + '/s \u00B7 Upgrade to $' + nextEps + '/s for $' + cost.toLocaleString();
      }
      const candidates = getCandidates(state.day);
      const c = candidates[1];
      return 'Hire ' + c.name + ' (' + c.emoji + ' ' + c.role + ') \u00B7 $' + c.earningsPerTick + '/s';
    },
    get action() {
      const w = state.workers.find(w => w.deskIndex === 1);
      if (!w) return 'Make the offer \uD83E\uDD1D';
      const cost = workerUpgradeCost(w);
      if (cost === null) return 'Max level \u2B50';
      return 'Upgrade ' + w.name + ' \u2013 $' + cost.toLocaleString();
    },
    get cancelLabel() {
      const w = state.workers.find(w => w.deskIndex === 1);
      return w ? 'Let ' + w.name + ' go' : 'Maybe in a minute';
    },
    perform() {
      const w = state.workers.find(w => w.deskIndex === 1);
      if (!w) {
        const c = getCandidates(state.day)[1];
        state.workers = [...state.workers.filter(w => w.deskIndex !== 1), { ...c, deskIndex: 1, level: 1 }];
        toast(c.emoji + ' ' + c.name + ' joined as ' + c.role + '! They\u2019ll earn $' + c.earningsPerTick + '/s passively. \uD83C\uDF89');
        playSound('complete'); save(); updateUI(); return;
      }
      const cost = workerUpgradeCost(w);
      if (cost === null) { toast(w.name + ' is already at max level. You\u2019re running a dream team.'); return; }
      if ((state.money || 0) < cost) { toast('\uD83D\uDCB0 You need $' + cost.toLocaleString() + ' to upgrade ' + w.name + '.'); return; }
      changeMoney(-cost);
      const newLevel = (w.level || 1) + 1;
      state.workers = state.workers.map(wk => wk.deskIndex === 1 ? { ...wk, level: newLevel } : wk);
      const newEps = workerEarnings({ ...w, level: newLevel });
      toast(w.emoji + ' ' + w.name + ' upgraded to Level ' + newLevel + '! Now earning $' + newEps + '/s. \uD83D\uDE80');
      playSound('complete'); save(); updateUI();
    },
    performCancel() {
      const w = state.workers.find(w => w.deskIndex === 1);
      if (w) {
        state.workers = state.workers.filter(wk => wk.deskIndex !== 1);
        toast(w.name + ' has left the building. Good luck out there.');
        save(); updateUI();
      }
    },
  },
  coffee: {
    icon: 'coffee', eyebrow: 'THE COFFEE CORNER',
    get title() { return state.completed.includes('coffee') ? 'Already fuelled up.' : 'Time for a top-up.'; },
    description: 'A battered espresso machine that makes genuinely great coffee. Two shots, every time. The kind of focus that comes in a cup.',
    get detail() { return state.completed.includes('coffee') ? 'Already done today \u2714' : '+35 stamina \u00B7 Click to brew'; },
    get action() { return state.completed.includes('coffee') ? 'One cup is enough' : 'Brew a double shot \u2615'; },
    perform() {
      if (state.completed.includes('coffee')) { toast('\u2615 You\u2019ve already had your coffee. Any more and you\u2019ll be vibrating.'); return; }
      changeEnergy(35); complete('coffee');
      toast('\u2615 Double shot down. Stamina +35. Time to build.'); playSound('coffee');
    },
  },
  sleep: {
    icon: 'bed', eyebrow: 'END THE DAY',
    get title() {
      const done = state.completed.length;
      const total = TASKS.length;
      if (done >= total) return 'Day complete. Time to rest.';
      return 'Sleep now? ' + (total - done) + ' task' + (total - done > 1 ? 's' : '') + ' left.';
    },
    get description() {
      const done = state.completed.length;
      const total = TASKS.length;
      if (done >= total) return 'Every task is done. You\u2019ve earned this. Sleep well.';
      return 'There\u2019s still ' + (total - done) + ' task' + (total - done > 1 ? 's' : '') + ' left today. But if you\u2019re done, you\u2019re done. Tomorrow is another day.';
    },
    detail: 'Ends the day and advances to the next one.',
    get action() {
      return state.completed.length >= TASKS.length ? 'Sleep \uD83D\uDCA4' : 'Call it a day anyway';
    },
    perform() {
      advanceDay();
    },
  },
  pills: {
    icon: 'pills', eyebrow: 'THE VITAMIN SHELF',
