// ── Cycling machine ───────────────────────────────────────────────────────
function mountBike() {
  if (isCycling) return;
  isCycling = true; pedalPower = 0; bikeBreakdown = 0;
  $('#cycling-overlay').hidden = false;
  updateUI();
  toast('\uD83D\uDEB4 On the bike. Press SPACE to pedal and generate electricity. ESC to stop.');
}

function dismountBike(broken) {
  isCycling = false; pedalPower = 0;
  $('#cycling-overlay').hidden = true;
  updateUI();
  if (broken) toast('\uD83D\uDD25 Generator overloaded! Chain snapped. Need to cool down before next session.');
  else toast('\uD83D\uDEB4 Off the bike.');
}

// ── Day advance ───────────────────────────────────────────────────────────
function advanceDay() {
  const completedDay = state.day;
  const overlay = $('#day-end-overlay');
  const dayEarnings = DAY_PROGRESS[completedDay - 1].workEarnings;
  const workerPassive = state.workers.reduce((sum, w) => sum + workerEarnings(w), 0);

  $('#day-end-progress').textContent = 'DAY ' + completedDay + ' / 10 COMPLETE';
  const fill = $('#day-end-bar-fill');
  fill.style.width = '0%';
  setTimeout(() => { fill.style.width = (completedDay / 10 * 100) + '%'; }, 80);

  const titles = [
    'Day 1 complete.', 'Two down.', 'Halfway to halfway.', 'Day 4 done.',
    'The halfway mark.', 'Day 6 in the books.', 'Seven days in.', 'Day 8 done.',
    'One more day.', 'You built it.',
  ];
  $('#day-end-title').textContent = titles[completedDay - 1] || 'Day done.';

  const bodies = [
    'Not bad for day one. You\u2019ve got nine more to make this real.',
    'Day two in the books. It\u2019s getting real.',
    'Three days of building. You\u2019re in a rhythm now.',
    'Four days down. The idea is becoming a product.',
    'Halfway. Five days left. The hard part is also the good part.',
    'Day six done. Two-thirds of the way there.',
    'Seven days of grinding. Three to go.',
    'Eight days. Almost there. Don\u2019t stop now.',
    'One more day. Tomorrow you ship.',
    'Ten days. You built a startup. That\u2019s not nothing \u2014 that\u2019s everything.',
  ];
  const workerLine = workerPassive > 0 ? ' Team earned $' + workerPassive.toFixed(1) + '/s passively.' : '';
  $('#day-end-body').textContent = (bodies[completedDay - 1] || '') + workerLine;
  overlay.hidden = false;

  const btn = $('#day-end-btn');
  if (completedDay >= 10) {
    btn.textContent = 'Play Again';
    btn.onclick = () => { overlay.hidden = true; resetGame(); };
  } else {
    btn.textContent = 'Start Day ' + (completedDay + 1);
    btn.onclick = () => {
      overlay.hidden = true;
      state.day = completedDay + 1;
      state.completed = [];
      state.energy = Math.min(100, state.energy + 30);
      state.minutes = 540;
      peptideShots = 0;
      save(); updateUI();
    };
  }
}

// ── Reset ─────────────────────────────────────────────────────────────────
function resetGame() {
  state = newState(); path = []; pendingInteraction = null; clockAccumulator = 0; saveAccumulator = 0;
  energyDrainAccumulator = 0; electricDrainAccumulator = 0; workerEarnAccumulator = 0;
  drainInterval = 3; speed = 2.65; peptideShots = 0; lowEnergyWarned = false; lowElecWarned = false;
  direction = { x: 1, y: 0 }; sprinting = false; sprintDrainAccumulator = 0;
  dashTrail = []; dashLocked = false; jumpState = null; vaultCooldown = 0; hopSlowdown = 0;
  blinkCooldown = 0; sittingOnSofa = false; sofaRestAccumulator = 0; sofaRecline = 0;
  isCycling = false; pedalPower = 0; bikeBreakdown = 0;
  save(); updateUI();
}

// ── updateUI ──────────────────────────────────────────────────────────────
function updateUI() {
  // Energy bar
  const energyPct = state.energy;
  $('#energy-fill').style.width = energyPct + '%';
  $('#energy-fill').classList.toggle('low', energyPct < 20);
  $('#energy-value').textContent = Math.round(energyPct);
  $('#energy-bar').setAttribute('aria-valuenow', Math.round(energyPct));

  // Elec bar
  const elecPct = state.elec;
  $('#elec-fill').style.width = elecPct + '%';
  $('#elec-fill').classList.toggle('low', elecPct < 20);
  $('#elec-value').textContent = Math.round(elecPct);
  $('#elec-bar').setAttribute('aria-valuenow', Math.round(elecPct));

  // Money
  $('#money-value').textContent = '$' + Math.floor(state.money || 0).toLocaleString();

  // Day
  $('#hud-day').textContent = 'DAY ' + state.day + ' / 10';

  // Tasks
  document.querySelectorAll('[data-task]').forEach(btn => {
    const id = btn.dataset.task;
    const done = state.completed.includes(id);
    btn.classList.toggle('complete', done);
    const dot = btn.querySelector('.hud-task-dot');
    if (dot) dot.style.background = done ? '#58c858' : '';
  });

  // Work button label
  const workBtn = document.querySelector('[data-task="work"]');
  if (workBtn) {
    workBtn.querySelector('.hud-task-dot') && null;
    const span = workBtn.querySelector('span:not(.hud-task-dot)') || workBtn.lastChild;
    if (span && span.nodeType === Node.TEXT_NODE) {
      workBtn.replaceChild(document.createTextNode(DAY_PROGRESS[state.day - 1].workAction), span);
    }
  }

  // Sound button
  $('#sound-button').setAttribute('aria-pressed', String(state.sound));
  $('#sound-button').setAttribute('aria-label', 'Turn sound ' + (state.sound ? 'off' : 'on'));

  // Pause button
  // (handled by setPaused)

  // Cycling overlay
  if (isCycling) {
    const pct = Math.min(100, pedalPower);
    $('#pedal-fill').style.width = pct + '%';
    $('#pedal-val').textContent = Math.round(pct);
    $('#pedal-bar').setAttribute('aria-valuenow', Math.round(pct));
    const chargeLabel = $('#cycling-charge-label');
    if (pedalPower < 25) chargeLabel.textContent = 'GET UP TO SPEED';
    else if (pedalPower < 50) chargeLabel.textContent = 'CHARGING \u26A1';
    else if (pedalPower < 75) chargeLabel.textContent = 'DOUBLE CHARGE \u26A1\u26A1';
    else if (pedalPower < 100) chargeLabel.textContent = 'TRIPLE CHARGE \u26A1\u26A1\u26A1';
    else chargeLabel.textContent = 'OVERLOAD! STOP NOW \uD83D\uDD25';
  }
}

// ── Clock display ─────────────────────────────────────────────────────────
function formatClock(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  const ampm = h >= 12 ? 'PM' : 'AM';
  const hour = h % 12 || 12;
  return hour + ':' + String(m).padStart(2, '0') + ' ' + ampm;
}

// ── Pathfinding / movement helpers ────────────────────────────────────────
function goTo(destination, interaction) {
  if (!destination) return;
  const target = nearestWalkable(destination.x, destination.y);
  if (!target) return;
  const newPath = findPath(state.founder, target);
  if (!newPath) return;
  path = newPath;
  pendingInteraction = interaction || null;
  if (sittingOnSofa) { sittingOnSofa = false; sofaRestAccumulator = 0; sofaRecline = 0; }
  if (isCycling) dismountBike(false);
}

function visit(id) {
  const obj = OBJECTS.find(o => o.action === id || o.id === id);
  if (obj && obj.target) goTo(obj.target, obj);
}

// ── Vault / parkour ───────────────────────────────────────────────────────
function tryVault() {
  if (jumpState || vaultCooldown > 0) return;
  if (state.energy < 6) { toast('Too drained to jump. Grab a coffee first. \u2615'); return; }
  const isSprintJump = (sprinting || dashLocked) && state.energy > 1;
  const dx = direction.x, dy = direction.y;
  const cx = state.founder.x, cy = state.founder.y;
  const reach = isSprintJump ? 0.9 : 0.6;
  const vaultable = OBJECTS.filter(o => VAULTABLE_TYPES.includes(o.type));
  let hit = null;
  for (const o of vaultable) {
    const padX = 0.1, padY = 0.1;
    const inX = cx + dx * reach > o.x - padX && cx + dx * reach < o.x + o.w + padX;
    const inY = cy + dy * reach > o.y - padY && cy + dy * reach < o.y + o.d + padY;
    if (inX && inY) { hit = o; break; }
  }
  if (!hit) {
    // Small hop over nothing
    hopSlowdown = 0.35;
    jumpState = { height: 0, vel: 2.8, landing: false };
    changeEnergy(-2);
    return;
  }
  const landX = cx + dx * (hit.w + 1.2);
  const landY = cy + dy * (hit.d + 1.2);
  const land = nearestWalkable(landX, landY);
  if (!land) return;
  jumpState = { height: 0, vel: 3.2, landing: false, target: land };
  changeEnergy(isSprintJump ? -4 : -3);
  playSound('vault');
  vaultCooldown = 0.3;
}

// ── Blink dash ────────────────────────────────────────────────────────────
function tryBlink() {
  if (blinkCooldown > 0) { toast('Blink cooling down\u2026 (' + Math.ceil(blinkCooldown) + 's)'); return; }
  if (state.energy < 10) { toast('Not enough stamina to blink. Need 10. \u26A1'); return; }
  const dist = 3.5;
  const tx = state.founder.x + direction.x * dist;
  const ty = state.founder.y + direction.y * dist;
  const target = nearestWalkable(tx, ty);
  if (!target) { toast('Nowhere to blink to.'); return; }
  const trail = [];
  for (let i = 1; i <= 5; i++) {
    trail.push({ x: state.founder.x + (target.x - state.founder.x) * (i / 5), y: state.founder.y + (target.y - state.founder.y) * (i / 5), alpha: 1 - i / 6 });
  }
  dashTrail = trail;
  state.founder = target;
  changeEnergy(-10);
  blinkCooldown = 4;
  path = [];
  playSound('blink');
}

// ── Main game loop ────────────────────────────────────────────────────────
let lastTime = null;
let paused = false;
let stepTimer = 0;

function tick(now) {
  requestAnimationFrame(tick);
  if (!renderer) return;

  const dt = lastTime === null ? 0 : Math.min((now - lastTime) / 1000, 0.1);
  lastTime = now;
  if (paused || dialog.open) return;

  // Clock
  clockAccumulator += dt;
  if (clockAccumulator >= 0.5) {
    state.minutes = Math.min(1079, state.minutes + 1);
    clockAccumulator -= 0.5;
    $('#clock').textContent = formatClock(state.minutes);
  }

  // Save periodically
  saveAccumulator += dt;
  if (saveAccumulator >= 10) { save(); saveAccumulator = 0; }

  // Energy drain
  energyDrainAccumulator += dt;
  if (energyDrainAccumulator >= drainInterval) {
    energyDrainAccumulator -= drainInterval;
    if (!sittingOnSofa) {
      changeEnergy(-1);
      if (state.energy <= 15 && !lowEnergyWarned) { lowEnergyWarned = true; toast('\u26A0\uFE0F Low stamina! Brew a coffee or take your vitamins.'); }
      if (state.energy > 20) lowEnergyWarned = false;
    }
  }

  // Electric drain
  if (state.lightOn || state.lampOn) {
    electricDrainAccumulator += dt;
    const interval = (state.lightOn && state.lampOn) ? 4 : 6;
    if (electricDrainAccumulator >= interval) {
      electricDrainAccumulator -= interval;
      changeElec(-1);
      if (state.elec <= 15 && !lowElecWarned) { lowElecWarned = true; toast('\u26A1 Low battery! Get on the cycling machine to recharge.'); }
      if (state.elec > 20) lowElecWarned = false;
    }
  }

  // Worker passive earnings
  if (state.workers && state.workers.length > 0) {
    workerEarnAccumulator += dt;
    if (workerEarnAccumulator >= 1) {
      const ticks = Math.floor(workerEarnAccumulator);
      workerEarnAccumulator -= ticks;
      let totalEarned = 0;
      for (const w of state.workers) { totalEarned += workerEarnings(w) * ticks; }
      changeMoney(totalEarned);
      // Update money display smoothly
      $('#money-value').textContent = '$' + Math.floor(state.money || 0).toLocaleString();
    }
  }

  // Sofa rest
  if (sittingOnSofa) {
    sofaRestAccumulator += dt;
    sofaRecline = Math.min(1, sofaRecline + dt * 2);
    if (sofaRestAccumulator >= 2) {
      sofaRestAccumulator -= 2;
      changeEnergy(3);
      updateUI();
    }
  }

  // Vault / jump physics
  if (vaultCooldown > 0) vaultCooldown -= dt;
  if (hopSlowdown > 0) hopSlowdown = Math.max(0, hopSlowdown - dt * 1.5);
  if (jumpState) {
    jumpState.height += jumpState.vel * dt * 28;
    jumpState.vel -= 12 * dt;
    if (jumpState.vel < 0 && jumpState.target && !jumpState.landing) {
      state.founder = { ...jumpState.target };
      path = [];
      jumpState.landing = true;
    }
    if (jumpState.height <= 0 && jumpState.vel < 0) {
      jumpState = null;
    }
  }

  // Blink cooldown
  if (blinkCooldown > 0) blinkCooldown = Math.max(0, blinkCooldown - dt);

  // Dash trail decay
  for (const t of dashTrail) t.alpha = Math.max(0, t.alpha - dt * 3);
  dashTrail = dashTrail.filter(t => t.alpha > 0);

  // Sprint drain
  if (sprinting || dashLocked) {
    sprintDrainAccumulator += dt;
    if (sprintDrainAccumulator >= 0.4) {
      sprintDrainAccumulator -= 0.4;
      changeEnergy(-2);
      if (state.energy <= 0) { sprinting = false; dashLocked = false; toast('Exhausted! Slow down.'); }
    }
  }

  // Keyboard movement
  if (!sittingOnSofa && !isCycling) {
    const up    = keys.has('ArrowUp')    || keys.has('w') || keys.has('W');
    const down  = keys.has('ArrowDown')  || keys.has('s') || keys.has('S');
    const left  = keys.has('ArrowLeft')  || keys.has('a') || keys.has('A');
    const right = keys.has('ArrowRight') || keys.has('d') || keys.has('D');

    if (up || down || left || right) {
      path = [];
      pendingInteraction = null;
      let dx = 0, dy = 0;
      if (up)    dy -= 1;
      if (down)  dy += 1;
      if (left)  dx -= 1;
      if (right) dx += 1;
      if (dx !== 0 || dy !== 0) {
        const len = Math.hypot(dx, dy);
        dx /= len; dy /= len;
        direction = { x: dx, y: dy };
      }
      const spd = (sprinting || dashLocked) ? speed * 1.8 : speed * (1 - hopSlowdown * 0.4);
      const nx = state.founder.x + dx * spd * dt;
      const ny = state.founder.y + dy * spd * dt;
      if (isWalkable(nx, ny)) { state.founder = { x: nx, y: ny }; }
      else if (isWalkable(nx, state.founder.y)) { state.founder = { x: nx, y: state.founder.y }; }
      else if (isWalkable(state.founder.x, ny)) { state.founder = { x: state.founder.x, y: ny }; }

      stepTimer += dt;
      if (stepTimer >= 0.28) { stepTimer = 0; playSound('step'); }
      complete('walk');
    }
  }

  // Path following
  if (path.length > 0 && !sittingOnSofa) {
    const target = path[0];
    const dx = target.x - state.founder.x;
    const dy = target.y - state.founder.y;
    const dist = Math.hypot(dx, dy);
    const spd = speed * (1 - hopSlowdown * 0.4);
    if (dist < spd * dt + 0.02) {
      state.founder = { ...target };
      path.shift();
      if (path.length === 0 && pendingInteraction) {
        const pi = pendingInteraction;
        pendingInteraction = null;
        openInteraction(pi);
      }
    } else {
      const nx = state.founder.x + (dx / dist) * spd * dt;
      const ny = state.founder.y + (dy / dist) * spd * dt;
      if (isWalkable(nx, ny)) { state.founder = { x: nx, y: ny }; }
      direction = { x: dx / dist, y: dy / dist };
      stepTimer += dt;
      if (stepTimer >= 0.28) { stepTimer = 0; playSound('step'); }
      complete('walk');
    }
  }

  // Distance tracking
  state.distance = (state.distance || 0) + Math.hypot(
    state.founder.x - (renderer._lastPos?.x ?? state.founder.x),
    state.founder.y - (renderer._lastPos?.y ?? state.founder.y)
  );
  renderer._lastPos = { ...state.founder };

  // Render
  const moving = path.length > 0 || keys.has('ArrowUp') || keys.has('ArrowDown') || keys.has('ArrowLeft') || keys.has('ArrowRight') || keys.has('w') || keys.has('W') || keys.has('a') || keys.has('A') || keys.has('s') || keys.has('S') || keys.has('d') || keys.has('D');
  renderer.render({
    founder: state.founder,
    path,
    hovered,
    hoverFloor,
    direction,
    moving,
    time: now,
    jumpHeight: jumpState ? Math.max(0, jumpState.height) : 0,
    sprinting: sprinting || dashLocked,
    dashTrail,
    lightOn: state.lightOn !== false,
    lampOn: state.lampOn !== false,
    sittingOnSofa,
    sofaRecline,
    minutes: state.minutes,
    isCycling,
    pedalPower,
    bikeBreakdown,
    workers: state.workers || [],
  });
}

// ── Interaction dialog ────────────────────────────────────────────────────
function openInteraction(o) {
  const id = o.action || (o.type === 'plant' ? 'plant' : o.id);
  const config = interactions[id];
  if (!config) return;
  hoverLabel.hidden = true;
  keys.clear();
  dialogKind = id;
  $('#dialog-icon').innerHTML = config.icon === 'plant' ? '\uD83C\uDF31' : config.icon === 'bed' ? '\uD83D\uDECF\uFE0F' : config.icon === 'pills' ? '\uD83D\uDC8A' : '<svg><use href="#i-' + config.icon + '"/></svg>';
  $('#dialog-eyebrow').textContent = config.eyebrow;
  $('#dialog-title').textContent = config.title;
  $('#dialog-description').textContent = config.description;
  $('#dialog-detail').textContent = config.detail;
  $('#dialog-action').textContent = config.action;
