import sys

content = r"""import { OBJECTS, TASKS, SAVE_KEY, START, newState, parseSave, findPath, canTravel, isWalkable, nearestWalkable, DAY_PROGRESS, VAULTABLE_TYPES, getCandidates, WORKER_UPGRADE_COSTS, FOUNDER_UPGRADES } from './world.js';

const $ = (s) => document.querySelector(s);
const canvas = $('#game');
const ctx = canvas.getContext('2d');

// Lazy-load renderer
let renderer;
async function getRenderer() {
  if (!renderer) {
    const { Renderer } = await import('./renderer.js');
    renderer = new Renderer(canvas, ctx);
  }
  return renderer;
}

// State
let state = parseSave(localStorage.getItem(SAVE_KEY));
let path = [];
let pendingInteraction = null;
let clockAccumulator = 0;
let saveAccumulator = 0;
let energyDrainAccumulator = 0;
let electricDrainAccumulator = 0;
let workerEarnAccumulator = 0;
let drainInterval = 3;
let speed = 2.65;
let peptideShots = 0;
let lowEnergyWarned = false;
let lowElecWarned = false;
let direction = { x: 1, y: 0 };
let sprinting = false;
let sprintDrainAccumulator = 0;
let dashTrail = [];
let dashLocked = false;
let jumpState = null;
let vaultCooldown = 0;
let hopSlowdown = 0;
let blinkCooldown = 0;
let sittingOnSofa = false;
let sofaRestAccumulator = 0;
let sofaRecline = 0;
let isCycling = false;
let pedalPower = 0;
let bikeBreakdown = 0;
let audioContext;
let dialogAction = null;
let dialogCancelAction = null;
let dialogKind = null;
const keys = new Set();
const dialog = $('#interaction-dialog');
const hoverLabel = $('#hover-label');
let hovered = null;
let hoverFloor = null;
let storageAvailable = false;
try { localStorage.setItem('_t', '1'); localStorage.removeItem('_t'); storageAvailable = true; } catch {}

// Audio
function getAudioContext() {
  if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();
  return audioContext;
}
function playSound(type) {
  if (!state.sound) return;
  try {
    const ac = getAudioContext();
    const o = ac.createOscillator(); const g = ac.createGain();
    o.connect(g); g.connect(ac.destination);
    const t = ac.currentTime;
    if (type === 'step') {
      o.type = 'triangle'; o.frequency.setValueAtTime(180 + Math.random() * 40, t);
      g.gain.setValueAtTime(0.04, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.08);
      o.start(t); o.stop(t + 0.08);
    } else if (type === 'complete') {
      o.type = 'sine';
      o.frequency.setValueAtTime(520, t); o.frequency.setValueAtTime(780, t + 0.07);
      g.gain.setValueAtTime(0.12, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
      o.start(t); o.stop(t + 0.22);
    } else if (type === 'coffee') {
      o.type = 'sine';
      o.frequency.setValueAtTime(400, t); o.frequency.linearRampToValueAtTime(600, t + 0.15);
      g.gain.setValueAtTime(0.1, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
      o.start(t); o.stop(t + 0.3);
    } else if (type === 'vault') {
      o.type = 'square'; o.frequency.setValueAtTime(320, t); o.frequency.setValueAtTime(640, t + 0.04);
      g.gain.setValueAtTime(0.07, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.18);
      o.start(t); o.stop(t + 0.18);
    } else if (type === 'blink') {
      o.type = 'sawtooth'; o.frequency.setValueAtTime(880, t); o.frequency.exponentialRampToValueAtTime(220, t + 0.12);
      g.gain.setValueAtTime(0.09, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.14);
      o.start(t); o.stop(t + 0.14);
    }
  } catch {}
}

// Toast
let toastTimer;
const toastEl = $('#toast');
function toast(msg) {
  toastEl.textContent = msg;
  toastEl.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { toastEl.hidden = true; }, 3200);
}

// Save
function save() {
  if (!storageAvailable) return;
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(state)); } catch {}
}

// Task completion
function complete(id) {
  if (!state.completed.includes(id)) { state.completed = [...state.completed, id]; }
}

// Money & upgrade helpers
function changeEnergy(amount) { state.energy = Math.max(0, Math.min(100, state.energy + amount)); }
function changeElec(amount)  { state.elec   = Math.max(0, Math.min(100, state.elec   + amount)); }
function changeMoney(amount) { state.money  = Math.max(0, (state.money ?? 0) + amount); }

function hasUpgrade(id) { return (state.founderUpgrades || []).includes(id); }

function workEnergyCost() {
  if (hasUpgrade('deepwork')) return -5;
  if (hasUpgrade('focus'))    return 8;
  return 12;
}

function workMoneyMultiplier() {
  if (hasUpgrade('deepwork'))  return 2.0;
  if (hasUpgrade('speeddesk')) return 1.5;
  return 1.0;
}

function workerEarnings(worker) {
  const level = worker.level || 1;
  return Math.round(worker.earningsPerTick * Math.pow(1.5, level - 1) * 10) / 10;
}

function workerUpgradeCost(worker) {
  const level = worker.level || 1;
  if (level >= 3) return null;
  return WORKER_UPGRADE_COSTS[level];
}
"""

