 61 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 62 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 63 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 64 |   // Spiral outward in quarter-tile steps until we find a walkable point
 65 |   const step = 0.25;
 66 |   for (let r = step; r <= 3; r += step) {
 67 |     let best = null, bestDist = Infinity;
 68 |     const n = Math.ceil((r * 2) / step);
 69 |     for (let i = 0; i <= n; i++) {
 70 |       const t = i / n;
 71 |       for (const [cx, cy] of [
 72 |         [tx - r + t * r * 2, ty - r],
 73 |         [tx + r, ty - r + t * r * 2],
 74 |         [tx + r - t * r * 2, ty + r],
 75 |         [tx - r, ty + r - t * r * 2],
 76 |       ]) {
 77 |         const rx = Math.round(cx / step) * step;
 78 |         const ry = Math.round(cy / step) * step;
 79 |         if (!isWalkable(rx, ry, objects)) continue;
 80 |         const d = Math.hypot(rx - tx, ry - ty);
 81 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 82 |       }
 83 |     }
 84 |     if (best) return best;
 85 |   }
 86 |   return null;
 87 | }
