288 | export function parseSave(raw) {
289 |   const fresh = newState();
290 |   try {
291 |     const value = JSON.parse(raw);
292 |     if (!value || value.version !== 3) return fresh;
293 |     if (value.founder && isWalkable(value.founder.x, value.founder.y)) fresh.founder = { x: value.founder.x, y: value.founder.y };
294 |     if (Number.isFinite(value.energy)) fresh.energy = Math.max(0, Math.min(100, value.energy));
295 |     if (Number.isFinite(value.elec))   fresh.elec   = Math.max(0, Math.min(100, value.elec));
296 |     if (Number.isFinite(value.minutes)) fresh.minutes = Math.max(540, Math.min(1079, value.minutes));
297 |     if (Number.isFinite(value.distance)) fresh.distance = Math.max(0, Math.min(100000, value.distance));
298 |     if (Array.isArray(value.completed)) fresh.completed = TASKS.filter((id) => id !== 'sleep' && value.completed.includes(id));
299 |     fresh.sound = value.sound === true;
300 |     fresh.lightOn = value.lightOn !== false; // default to true if missing
301 |     fresh.lampOn = value.lampOn !== false;   // default to true if missing
302 |     if (Number.isFinite(value.day)) fresh.day = Math.max(1, Math.min(10, value.day));
303 |     if (Number.isFinite(value.money)) fresh.money = Math.max(0, value.money);
304 |     if (Array.isArray(value.workers)) {
305 |       fresh.workers = value.workers.filter(w =>
306 |         w && typeof w.name === 'string' && typeof w.role === 'string' &&
307 |         Number.isFinite(w.earningsPerTick) && Number.isFinite(w.deskIndex)
308 |       ).map(w => ({ ...w, level: Number.isFinite(w.level) ? Math.max(1, Math.min(3, w.level)) : 1 }))
309 |        .slice(0, 2); // max 2 workers
310 |     }
311 |     if (Array.isArray(value.founderUpgrades)) {
312 |       const validIds = new Set(['focus', 'speeddesk', 'deepwork']);
313 |       fresh.founderUpgrades = value.founderUpgrades.filter(id => validIds.has(id));
314 |     }
315 |     return fresh;
316 |   } catch { return fresh; }
317 | }

