292 |     const value = JSON.parse(raw);
293 |     if (!value || value.version !== 3) return fresh;
294 |     if (value.founder && isWalkable(value.founder.x, value.founder.y)) fresh.founder = { x: value.founder.x, y: value.founder.y };
295 |     if (Number.isFinite(value.energy)) fresh.energy = Math.max(0, Math.min(100, value.energy));
296 |     if (Number.isFinite(value.elec))   fresh.elec   = Math.max(0, Math.min(100, value.elec));
297 |     if (Number.isFinite(value.minutes)) fresh.minutes = Math.max(540, Math.min(1079, value.minutes));
298 |     if (Number.isFinite(value.distance)) fresh.distance = Math.max(0, Math.min(100000, value.distance));
299 |     if (Array.isArray(value.completed)) fresh.completed = TASKS.filter((id) => id !== 'sleep' && value.completed.includes(id));
300 |     fresh.sound = value.sound === true;
301 |     fresh.lightOn = value.lightOn !== false; // default to true if missing
302 |     fresh.lampOn = value.lampOn !== false;   // default to true if missing
303 |     if (Number.isFinite(value.day)) fresh.day = Math.max(1, Math.min(10, value.day));
304 |     if (Number.isFinite(value.money)) fresh.money = Math.max(0, value.money);
305 |     if (Array.isArray(value.workers)) {
306 |       fresh.workers = value.workers.filter(w =>
