  get title(){
    const s=state.cerealStock||0;
    if(s===0)return 'Completely bare. Needs restocking.';
    if(state.completed.includes('cereal'))return 'Bowl down. Good start.';
    return s+' serving'+(s===1?'':'s')+' left. Dig in.';
  },
  get description(){
    const s=state.cerealStock||0;
    if(s===0){const n=state.workers.length;return 'Empty boxes, an abandoned spoon, and a lot of startup regret. Restock for $25.'+(n>0?' Your team notices these things.':'');}
    if(state.completed.includes('cereal'))return 'You already had your bowl. Come back tomorrow for more.';
    return 'A solid lineup: Honey Loops, Frosted Crunch, and something called \"GrindFlakes.\" Genuinely good.';
  },
  get detail(){
    const s=state.cerealStock||0;
    const n=(state.workers||[]).filter(w=>!w.onStrike).length;
    if(s===0)return 'Restock for $25 · Gets 3 servings · +20 stamina per bowl'+(n>0?' · Workers stay happier longer':'');
    if(state.completed.includes('cereal'))return 'Come back tomorrow · '+s+' serving'+(s===1?'':'s')+' still on the shelf';
    return '+20 stamina · '+s+' serving'+(s===1?'':'s')+' remaining';
  },
  get action(){
    const s=state.cerealStock||0;
    if(s===0)return (state.money||0)>=25?'Restock – $25':'Can\'t afford restock ($25)';
    if(state.completed.includes('cereal'))return 'Already had a bowl today ✓';
    return 'Pour a bowl 🥣';
  },
  perform(){
    const s=state.cerealStock||0;
    if(s===0){
      if((state.money||0)<25){toast('💰 Need $25 to restock the cereal station.');return;}
      changeMoney(-25);state.cerealStock=3;
      const happyWorkers=(state.workers||[]).filter(w=>!w.onStrike);
      if(happyWorkers.length>0){
        state.workers=state.workers.map(w=>w.onStrike?w:{...w,strikeCountdown:(w.strikeCountdown||0)+60});
        const names=happyWorkers.map(w=>w.name).join(' & ');
        toast('🛒 Cereal restocked! 3 servings ready. '+names+' '+( happyWorkers.length===1?'is':'are')+' feeling appreciated. ✨');
      }else{
        toast('🛒 Cereal restocked! 3 servings ready. Grab a bowl.');
      }
      playSound('complete');save();updateUI();return;
    }
    if(state.completed.includes('cereal')){toast('🥣 Already had your bowl today.');return;}
    state.cerealStock=Math.max(0,s-1);
    changeEnergy(20);complete('cereal');
    toast('🥣 Bowl of GrindFlakes down. Stamina +20.'+(state.cerealStock===0?' That was the last one.':' '+state.cerealStock+' serving'+(state.cerealStock===1?'':'s')+' left.'));
    playSound('coffee');save();updateUI();
  },
},

